insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('rvb-wine-18','menu','Martini Asti DOCG',null,'{"id":"rvb-wine-18","name":"Martini Asti DOCG","category":"wine","subcategory":"Игристое","volume":"750 мл","price":"150 р.","description":"Ароматное сладкое игристое из Москато Бьянко. Во вкусе и аромате — персик, шалфей, груша и ананас.","taste":"Сладкое · Фруктовое · Ароматное","fact":"Asti Martini делают из сорта Москато Бьянко. Производитель рекомендует сочетать его с фруктами и десертами.","ingredients":[],"image":"assets/rvb-menu/wine/18.png","wineService":"Бутылка","imageKind":"photo","features":"","method":"","garnish":""}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
