insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('rvb-wine-22','menu','Moët & Chandon Brut Impérial',null,'{"id":"rvb-wine-22","name":"Moët & Chandon Brut Impérial","category":"wine","subcategory":"Шампанское","volume":"750 мл","price":"600 р.","description":"Шампанское с оттенками зелёного яблока, цитрусов, белых цветов и бриоши. Во вкусе — сочные белые фрукты и тонкие пузырьки.","taste":"Яблоко · Цитрус · Бриошь","fact":"В купаже Brut Impérial соединяются Пино Нуар, Менье и Шардоне.","ingredients":[],"image":"assets/rvb-menu/wine/22.png","wineService":"Бутылка","imageKind":"photo","features":"","method":"","garnish":""}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
